int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

// Returns top two (value, count) pairs from array
void top_two(int *arr, int len, int *v1, int *c1, int *v2, int *c2) {
    *c1 = 0; *c2 = 0; *v1 = -1; *v2 = -1;
    // sort and count
    int *tmp = malloc(len * sizeof(int));
    memcpy(tmp, arr, len * sizeof(int));
    qsort(tmp, len, sizeof(int), cmp);
    int i = 0;
    while (i < len) {
        int j = i, val = tmp[i], cnt = 0;
        while (j < len && tmp[j] == val) { j++; cnt++; }
        if (cnt > *c1) { *c2 = *c1; *v2 = *v1; *c1 = cnt; *v1 = val; }
        else if (cnt > *c2) { *c2 = cnt; *v2 = val; }
        i = j;
    }
    free(tmp);
}

