typedef struct {
    int key;
    int cnt;
    int used;
} Entry;

typedef struct {
    Entry *t;
    int size;
} Hash;

static unsigned int hash_int(unsigned int x) {
    x ^= x >> 16;
    x *= 0x7feb352dU;
    x ^= x >> 15;
    x *= 0x846ca68bU;
    x ^= x >> 16;
    return x;
}

static void hash_init(Hash *h, int n) {
    h->size = 1;
    while (h->size < n) h->size <<= 1;
    h->t = (Entry *)calloc(h->size, sizeof(Entry));
}

static void hash_add(Hash *h, int key) {
    unsigned int idx = hash_int((unsigned int)key) & (h->size - 1);
    while (h->t[idx].used) {
        if (h->t[idx].key == key) {
            h->t[idx].cnt++;
            return;
        }
        idx = (idx + 1) & (h->size - 1);
    }
    h->t[idx].used = 1;
    h->t[idx].key = key;
    h->t[idx].cnt = 1;
}

static void top2(Hash *h, int *v1, int *c1, int *v2, int *c2) {
    *v1 = *v2 = 0;
    *c1 = *c2 = 0;
    for (int i = 0; i < h->size; i++) {
        if (!h->t[i].used) continue;
        int v = h->t[i].key;
        int c = h->t[i].cnt;
        if (c > *c1) {
            *c2 = *c1; *v2 = *v1;
            *c1 = c;   *v1 = v;
        } else if (c > *c2) {
            *c2 = c;   *v2 = v;
        }
    }
}

