    // Top 2 from odd x Top 2 from even, pick best with different values
    int best = 0;
    int limit_odd = min((int)odd_sorted.size(), 2);
    int limit_even = min((int)even_sorted.size(), 2);

    for (int i = 0; i < limit_odd; i++) {
        for (int j = 0; j < limit_even; j++) {
