            if ((i & 1) == 0) {
                even.put(x, even.getOrDefault(x, 0) + 1);
            } else {
                odd.put(x, odd.getOrDefault(x, 0) + 1);
            }
        }

        int[] bestEven = topTwo(even);
        int[] bestOdd = topTwo(odd);

        int evenVal1 = bestEven[0], evenCnt1 = bestEven[1];
        int evenVal2 = bestEven[2], evenCnt2 = bestEven[3];
        int oddVal1 = bestOdd[0], oddCnt1 = bestOdd[1];
        int oddVal2 = bestOdd[2], oddCnt2 = bestOdd[3];

        int half = n / 2;
        int answer;

        if (evenVal1 != oddVal1) {
            answer = (half - evenCnt1) + (half - oddCnt1);
        } else {
            int option1 = (half - evenCnt1) + (half - oddCnt2);
            int option2 = (half - evenCnt2) + (half - oddCnt1);
            answer = Math.min(option1, option2);
        }

        System.out.println(answer);
    }

    // returns {value1, count1, value2, count2}
    static int[] topTwo(HashMap<Integer, Integer> map) {
        int v1 = -1, c1 = 0, v2 = -1, c2 = 0;
        for (Map.Entry<Integer, Integer> e : map.entrySet()) {
            int v = e.getKey();
            int c = e.getValue();
            if (c > c1) {
                v2 = v1; c2 = c1;
                v1 = v;  c1 = c;
            } else if (c > c2) {
                v2 = v;  c2 = c;
            }
        }
        return new int[]{v1, c1, v2, c2};
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

